-- Preserve historical appointments; retire obsolete options only for new bookings.
UPDATE services SET active=0;
UPDATE packages SET active=0;
INSERT OR IGNORE INTO package_services(package_id,service_id) SELECT p.id,s.id FROM packages p,services s WHERE p.slug='3-pack-60' AND s.slug IN ('therapeutic-massage_60','sports-massage_60','myofascial-unwinding_60');
INSERT OR IGNORE INTO package_services(package_id,service_id) SELECT p.id,s.id FROM packages p,services s WHERE p.slug='3-pack-90' AND s.slug IN ('therapeutic-massage_90','sports-massage_90','myofascial-unwinding_90');
